window.AUTH=window.AUTH||{};window.AUTH["18-9526"]={"d":"18-9526","id":"2019/18-9526","n":"McGirt v. Oklahoma","briefs":[{"k":"petitioner","label":"Brief of petitioner Jimcy McGirt","date":"2020-02-04","url":"https://www.supremecourt.gov/DocketPDF/18/18-9526/130940/20200204154659747_18-9526ts.pdf","side":"pet","n":69},{"k":"respondent","label":"Brief of respondent Oklahoma","date":"2020-03-13","url":"https://www.supremecourt.gov/DocketPDF/18/18-9526/138118/20200313143331033_18-9526bs.pdf","side":"res","n":74},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-03-20","url":"https://www.supremecourt.gov/DocketPDF/18/18-9526/138804/20200320212530248_18-9526bsacUnitedStates.pdf","side":"us","n":58},{"k":"reply","label":"Reply of petitioner Jimcy McGirt","date":"2020-04-10","url":"https://www.supremecourt.gov/DocketPDF/18/18-9526/141365/20200410132548715_18-9526%20rb.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=453","tr":true,"items":[{"t":"case","label":"Ammerman v. United States","cite":"216 F. 326","y":1914,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./216/326/","by":{"0":"31"}},{"t":"case","label":"Azar v. Allina Health Services","cite":"139 S. Ct. 1804","y":2019,"id":"2018/17-1484","sc":1,"sum":"Because the Department of Health and Human Services neglected its statutory notice-and-comment obligations when it revealed a new policy that dramatically—and retroactively—reduced Medicare payments to hospitals serving low-income patients, its policy must be vacated.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Buster v. Wright","cite":"135 F. 947","y":1905,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./135/947/","op":1,"by":{"0":"10, 36","1":"38, 39","3":"15"}},{"t":"case","label":"City of Sherrill v. Oneida Indian Nation of New York","cite":"544 U.S. 197","y":2005,"id":"2004/03-855","sc":1,"ar":3,"sum":"The Court held that standards of federal Indian law and federal equity precluded the Tribe from unilaterally reviving its ancient sovereignty over the land at issue.","sumSrc":"Oyez","by":{"0":"41","2":"40","3":"25"}},{"t":"case","label":"Colliflower v. Garland","cite":"342 F.2d 369","y":1965,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/342/369/","by":{"0":"53"}},{"t":"case","label":"Connecticut National Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"County of Yakima v. Confederated Tribes and Bands of Yakima Indian Nation","cite":"502 U.S. 251","y":1992,"id":"1991/90-408","sc":1,"op":1,"sum":"The Indian General Allotment Act of 1887 permits Yakima County to impose an ad valorem tax on reservation land patented in fee pursuant to the Act and owned by reservation Indians or the Yakima Indian Nation itself, but does not allow the county to enforce its excise tax on sales of such land.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Coyle v. Smith","cite":"221 U.S. 559","y":1911,"id":"1900-1940/221us559","sc":1,"sum":"This was congressional overreaching. States are on an equal footing to determine their own location for the seat of government.","sumSrc":"Oyez","by":{"0":"12, 38","1":"41"}},{"t":"case","label":"Cravatt v. State","cite":"825 P.2d 277","y":1992,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/825/277/","by":{"0":"44"}},{"t":"case","label":"DeCoteau v. District County Court for Tenth Judicial District","cite":"420 U.S. 425","y":1975,"id":"1974/73-1148","sc":1,"op":3,"sum":"The Lake Traverse Indian Reservation in South Dakota, created by an 1867 treaty, held terminated and returned to the public domain by an 1891 Act which, in ratification of a previously negotiated 1889 Agreement between the affected Indian tribe and the United States, not only opened all unallotted lands to settlement but also appropriated and vested in the tribe a sum certain per acre in payment for the express …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"29, 30, 31, 32, 42","2":"31","3":"14"}},{"t":"case","label":"Hagen v. Utah","cite":"510 U.S. 399","y":1994,"id":"1993/92-6281","sc":1,"op":14,"ar":1,"sum":"Petitioner, an Indian, was charged in Utah state court with distribution of a controlled substance in the town of Myton, which lies within the original boundaries of the Uintah Indian Reservation on land that was opened to non-Indian settlement in 1905. The trial court rejected petitioner's claim that it lacked. jurisdiction over him because he was an Indian and the crime had been committed in \"Indian country,\" see …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 22, 24, 30","1":"29, 32, 40","2":"5, 7, 25","3":"12"}},{"t":"case","label":"Harjo v. Kleppe","cite":"420 F. Supp. 1110","y":1976,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./420/1110/","by":{"0":"11, 12, 13, 30, 37","1":"39","2":"30","3":"15"}},{"t":"case","label":"Henson v. Santander Consumer USA Inc.","cite":"137 S. Ct. 1718","y":2017,"id":"2016/16-349","sc":1,"sum":"The Court determined that a party that purchases a debt and attempts to collect the debt for its own account is not a “debt collector” subject to the Fair Debt Collection Practices Act (FDCPA).","sumSrc":"Oyez","by":{"0":"3"}},{"t":"case","label":"Herrera v. Wyoming","cite":"139 S. Ct. 1686","y":2019,"id":"2018/17-532","sc":1,"sum":"Wyoming’s statehood did not abrogate the Crow Tribe’s 1868 federal treaty right to hunt on the “unoccupied lands of the United States”; the lands of the Bighorn National Forest did not become categorically “occupied” when the forest was created.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"39","1":"41"}},{"t":"case","label":"Indian Country, U.S.A., Inc. v. Oklahoma ex rel. Oklahoma Tax Commission","cite":"829 F.2d 967","y":1987,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/829/967/","by":{"0":"47"}},{"t":"case","label":"Johnson v. Riddle","cite":"240 U.S. 467","y":1916,"id":"scdb/1915-122","sc":1,"sum":"Under the provisions relating to town sites, in the Atoka Agreement bfetween the United States and the Choctaw and Chickasaw tribes (found in Act of June 28, 1898, c. 517; 30 Stat. 495, 505, 508),-the preferential right to purchase improved town lots was conferred upon the owner of “permanent, substantial, and valuable improvements, other than fences) tillage, and temporary houses,” without regard' to.the lawfulness …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9"}},{"t":"case","label":"Joplin Mercantile Co. v. United States","cite":"236 U.S. 531","y":1915,"id":"scdb/1914-234","sc":1,"sum":"A mere conspiracy without overt acts done to effect its object is not indictable under § 37, Judicial Code, and where the averment respecting the formation of the conspiracy refers to no other clause of the indictment for certainty, it must be interpreted as it stands, and in the absence of a distinct averment that the conspiracy was formed to introduce liquors into Indian country within Oklahoma from without the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31","1":"19"}},{"t":"case","label":"Mattz v. Arnett","cite":"412 U.S. 481","y":1973,"id":"1972/71-1182","sc":1,"op":5,"sum":"The Klamath River Reservation was not terminated by the Act of June 17, 1892, and the land within the reservation boundaries is still Indian country, within theoneaning of 18 U. S. C. § 1151.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45, 46, 52","1":"32"}},{"t":"case","label":"Mertens v. Hewitt Associates","cite":"508 U.S. 248","y":1993,"id":"1992/91-1671","sc":1,"sum":"ERISA does not authorize suits for money damages against nonfiduciaries who knowingly participate in a fiduciary's breach of fiduciary duty. ERISA §502(a)(3) permits plan participants to bring civil actions to obtain \"appropriate equitable relief\" to redress violations of the statute or a plan. Assuming, arguendo,that this creates a cause of action against nonfiduciaries who knowingly assist in a fiduciary's breach …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Metlakatla Indian Community v. Egan","cite":"369 U.S. 45","y":1962,"id":"1961/2_0","sc":1,"sum":"The Court held that the Annette Islands were turned into a reservation for the Metlakatla Indians specifically to protect them from outside intrusion or exploitation. The proclamation that established the reservation also gave the Secretary of the Interior authority to prescribe rules governing fishing and other activities on the islands.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Michigan v. Bay Mills Indian Community","cite":"572 U.S. 782","y":2014,"id":"2013/12-515","sc":1,"op":3,"sum":"The Court held that Indian tribes have sovereign immunity that can only be revoked by Congress, and that the immunity extends to their commercial activities, even if they are not on their protected land.","sumSrc":"Oyez","by":{"0":"20, 34"}},{"t":"case","label":"Minnesota v. Mille Lacs Band of Chippewa Indians","cite":"526 U.S. 172","y":1999,"id":"1998/97-1337","sc":1,"sum":"Authored by Justice Sandra Day O'Connor, the Court ruled that the Mille Lacs Band of Chippewa Indians does have usufructuary rights that were guaranteed to them by the 1837 treaty.","sumSrc":"Oyez","by":{"0":"21, 39"}},{"t":"case","label":"Montana v. United States","cite":"450 U.S. 544","y":1981,"id":"1980/79-1128","sc":1,"op":2,"sum":"By a tribal regulation, the Crow Tribe of Montana sought to prohibit hunting and fishing within its reservation by anyone who is not a member of the Tribe. Relying on its purported ownership of the bed of the Big Horn River, on treaties which created its reservation, and on its inherent power as a sovereign, the Tribe claimed authority to prohibit hunting and fishing by nonmembers of the Tribe even on lands within …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","1":"45","3":"6"}},{"t":"case","label":"Morris v. Hitchcock","cite":"194 U.S. 384","y":1904,"id":"scdb/1903-115","sc":1,"sum":"The constitutionality of the Curtis Act, 30 Stat. 495, for the protection of the Indian Territory has been settled by this court and is not now open to question. Stephens v. Cherokee Nation, 174 U. S. 445; Cherokee Nation v. Hitchcock, 187 U. S. 294.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10, 36","1":"38","2":"15","3":"14"}},{"t":"case","label":"Morris v. Hitchcock","cite":"21 App. D.C. 565","y":1903,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/App.%20D.C./21/565/","by":{"0":"10, 36"}},{"t":"case","label":"Murphy v. Royal","cite":"875 F.3d 896","y":2017,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/875/896/","op":6,"by":{"0":"passim","1":"31","2":"2, 6","3":"3"}},{"t":"case","label":"Muscogee (Creek) Nation v. Hodel","cite":"851 F.2d 1439","y":1988,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/851/1439/","op":5,"by":{"0":"9","2":"31, 34"}},{"t":"case","label":"National Association of Manufacturers v. Department of Defense","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Nebraska v. Parker","cite":"136 S. Ct. 1072","y":2016,"id":"2015/14-1406","sc":1,"sum":"The Court determined that the passage of the 1882 Act by Congress did not diminish the original boundaries of the Omaha Indian Reservation.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 29, 31, 35, 40, 42","2":"5, 7","3":"12, 17, 18, 25"}},{"t":"case","label":"Negonsott v. Samuels","cite":"507 U.S. 99","y":1993,"id":"1992/91-5397","sc":1,"op":2,"sum":"Petitioner Negonsott, a member of the Kickapoo Tribe and a resident of the Kickapoo Reservation in Kansas, was convicted by a County District Court jury of aggravated battery for shooting another Indian on the reservation. The court set aside the conviction on the ground that the Federal Government had exclusive jurisdiction to prosecute Negonsott for the shooting under the Indian Major Crimes Act, 18 U. S. C. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45, 46, 51","1":"27","2":"2"}},{"t":"case","label":"Nevada Department of Human Resources v. Hibbs","cite":"538 U.S. 721","y":2003,"id":"2002/01-1368","sc":1,"sum":"The Court held that State employees may recover money damages in federal court in the event of the State's failure to comply with the FMLA's family-care provision.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Nevada v. Hicks","cite":"533 U.S. 353","y":2001,"id":"2000/99-1994","sc":1,"sum":"A unanimous Court held that \"[b]ecause the Fallon Paiute-Shoshone Tribes lacked legislative authority to restrict, condition, or otherwise regulate the ability of state officials to investigate off-reservation violations of state law, they also lacked adjudicative authority to hear respondent's claim that those officials violated tribal law in the performance of their duties. \"[S]ince the lack of authority is clear,\" continued Scalia, \"there is no need to exhaust the jurisdictional dispute in tribal court.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"New Prime Inc. v. Oliveira","cite":"139 S. Ct. 532","y":2019,"id":"2018/17-340","sc":1,"op":2,"sum":"A court should determine whether the Federal Arbitration Act’s §1 exclusion for disputes involving the “contracts of employment” of certain transportation workers applies before ordering arbitration; here, truck driver Oliveira’s independent contractor operating agreement with New Prime falls within that exception.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"20"}},{"t":"case","label":"Oneida County. v. Oneida Indian Nation of New York","cite":"470 U.S. 226","y":1985,"id":"1984/83-1065","sc":1,"sum":"Respondent Indian Tribes (hereafter respondents) brought an action in Federal District Court against petitioner counties (hereafter petitioners), alleging that respondents' ancestors conveyed tribal land to New York State, under a 1795 agreement that violated the Nonintercourse Act of 1793-which provided that no person or entity could purchase Indian land without the Federal Government's approval-and that thus the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","3":"16"}},{"t":"case","label":"Perry v. Merit Systems Protection Board","cite":"137 S. Ct. 1975","y":2017,"id":"2016/16-399","sc":1,"op":1,"sum":"The Court determined that a Merit Systems Protection Board decision to dismiss a case with mixed claims on jurisdictional grounds is subject to judicial review in district court.","sumSrc":"Oyez","by":{"0":"4"}},{"t":"case","label":"Plains Commerce Bank v. Long Family Land & Cattle Co.","cite":"554 U.S. 316","y":2008,"id":"2007/07-411","sc":1,"sum":"On this issue, the Court held unanimously that tribal courts do not have jurisdiction to hear disputes concerning non- Indian banks' sales of their own lands. Writing for the Court, Chief Justice John G. Roberts stated that although tribal courts have jurisdiction to regulate conduct occurring on tribal lands, that jurisdiction is lost once title to the land passes into the hands of non-Indians.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Puerto Rico v. Sanchez Valle","cite":"136 S. Ct. 1863","y":2016,"id":"2015/15-108","sc":1,"sum":"The Court held that Puerto Rico and the U.S. federal government are the same sovereign entity for the purpose of the Double Jeopardy Clause.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"op":12,"sum":"To give effect to § 5322(a)'s \"willfulness\" requirement, the Government must prove that the defendant acted with knowledge that the structuring he or she undertook was unlawful, not simply that the defendant's purpose was to circumvent a bank's reporting obligation. Section 5324 itself forbids structuring with a \"purpose of evading the [§ 5313(a)] reporting requirements,\" and the lower courts erred in treating the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20"}},{"t":"case","label":"Raygor v. Regents of University of Minnesota","cite":"534 U.S. 533","y":2002,"id":"2001/00-1514","sc":1,"sum":"The Court held that the Board of Regents of the University of Minnesota never consented to suit in federal court on Raygor and Goodrich's state law claims and that the federal supplemental jurisdiction statute does not toll the period of limitations for state law claims asserted against nonconsenting state defendants that are dismissed on Eleventh Amendment grounds.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Rosebud Sioux Tribe v. Kneip","cite":"430 U.S. 584","y":1977,"id":"1976/75-562","sc":1,"op":10,"ar":2,"sum":"Recognizing that a statute “cannot, and should not, be read as if it were the frst time Congress had addressed itself to” disestablishment when prior statutes also indicate congressional intent.","sumSrc":"opinion","by":{"0":"22, 24","1":"31, 32, 40","2":"26, 27","3":"12"}},{"t":"case","label":"Seymour v. Superintendent of Washington State Penitentiary","cite":"368 U.S. 351","y":1962,"id":"1961/62","sc":1,"op":4,"ar":1,"sum":"Holding that allotment Act “did no more than open the way for non-Indian settlers to own land on the reservation”.","sumSrc":"opinion","by":{"0":"22, 25, 50","1":"29, 31"}},{"t":"case","label":"Solem v. Bartlett","cite":"465 U.S. 463","y":1984,"id":"1983/82-1253","sc":1,"op":28,"ar":13,"sum":"The Act did not diminish the reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"6, 9, 29, 31, 32, 35, 37","2":"5, 22, 24, 25, 27","3":"12, 17"}},{"t":"case","label":"South Dakota v. Yankton Sioux Tribe","cite":"522 U.S. 329","y":1998,"id":"1997/96-1581","sc":1,"op":17,"ar":2,"sum":"The Court held that the 1894 statute's operative language and the circumstances surrounding its passage demonstrate that Congress intended to diminish the Yankton Reservation and as a result the unallotted lands ceded did not retain reservation status.","sumSrc":"Oyez","by":{"0":"23, 26, 30","1":"29, 31, 32, 35, 36, 40, 42","2":"5, 7, 24, 27, 28"}},{"t":"case","label":"Southern Surety Co. v. Oklahoma","cite":"241 U.S. 582","y":1916,"id":"scdb/1915-155","sc":1,"sum":"By reason of the conditions arising out of the presence of the Five Civilized Tribes no organized territorial government was ever established in the Indian Territory; and, in the absence of an organized local government, prosecutions for crime were, regardless of their nature, commenced and prosecuted in the name of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"State ex rel. May v. Seneca-Cayuga Tribe of Oklahoma","cite":"711 P.2d 77","y":1985,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/711/77/","by":{"0":"15, 44"}},{"t":"case","label":"State v. Brooks","cite":"763 P.2d 707","y":1988,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/763/707/","by":{"0":"44","2":"37"}},{"t":"case","label":"State v. Klindt","cite":"782 P.2d 401","y":1989,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P.2d/782/401/","op":3,"by":{"0":"14-15, 44","1":"15","2":"36, 37"}},{"t":"case","label":"Tillett v. Lujan","cite":"931 F.2d 636","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/931/636/","by":{"0":"53"}},{"t":"case","label":"United States Express Co. v. Friedman","cite":"191 F. 673","y":1911,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./191/673/","by":{"0":"32","1":"18"}},{"t":"case","label":"United States v. Creek Nation","cite":"476 F.2d 1290","y":1973,"court":"Ct. Cl.","url":"https://www.courtlistener.com/c/F.2d/476/1290/","by":{"0":"5"}},{"t":"case","label":"United States v. John","cite":"437 U.S. 634","y":1978,"id":"1977/77-836","sc":1,"op":1,"ar":1,"sum":"Lands designated as a reservation for Choctaw Indians residing in central Mississippi held, on the basis of the history of the relations between the Mississippi Choctaws and the United States, to be \"Indian country,\" as defined in 18 U. S. C. § 1151 (1976 ed.) to include \"all land within the limits of any Indian reservation under the jurisdiction of the United States Government,\" and as used in the Major Crimes Act, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45","1":"16, 26","2":"2","3":"3, 7"}},{"t":"case","label":"United States v. Ramsey","cite":"271 U.S. 467","y":1926,"id":"scdb/1925-135","sc":1,"sum":"Noting that the general “authority of the United States … to punish crimes … not committed by or against Indians, [i]s ended by the grant of statehood,” but federal “authority in respect of crimes committed by or against Indians continue[s] … as it was before”.","sumSrc":"brief:0","by":{"0":"48, 50"}},{"t":"case","label":"United States v. Sands","cite":"968 F.2d 1058","y":1992,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/968/1058/","op":2,"by":{"0":"43, 44, 50","2":"37"}},{"t":"case","label":"viii United States v. Wright","cite":"229 U.S. 226","y":1913,"id":"scdb/1912-230","sc":1,"sum":"In determining the effect of statutes regarding the introduction of liquor into Indian country, within the territorial limits of Oklahoma, every consideration arising out of the guardianship of the Federal Government over the Indians and control of their land indicate that as to them the liquor prohibition should be maintained after Statehood so far as consistent with the control of the State over its internal …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32","1":"17, 36"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26"}},{"t":"case","label":"Washington State Department of Licensing v. Cougar Den, Inc.","cite":"139 S. Ct. 1000","y":2019,"id":"2018/16-1498","sc":1,"sum":"The Supreme Court of Washington’s judgment—that the “right to travel” provision of the 1855 Treaty Between the United States and the Yakama Nation of Indians pre-empts the State’s fuel tax as applied to Cougar Den’s importation of fuel by public highway for sale within the reservation—is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 41","1":"40"}},{"t":"case","label":"Welch v. United States","cite":"136 S. Ct. 1257","y":2016,"id":"2015/15-6418","sc":1,"sum":"The Court held that the rule the Supreme Court announced in Johnson v. United States regarding what constitutes a violent offense for the purposes of sentencing under the Armed Career Criminal Act applies retroactively.","sumSrc":"Oyez","by":{"0":"43"}},{"t":"case","label":"White Mountain Apache Tribe v. Bracker","cite":"448 U.S. 136","y":1980,"id":"1979/78-1177","sc":1,"op":2,"sum":"The Arizona taxes are pre-empted by federal law. Cf. Warren Trading Post Co. v. Arnzona Tax Comm'n, 380 U. S. 685.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","1":"45"}},{"t":"case","label":"Wisconsin Central Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"Woodward v. De Graffenried","cite":"238 U.S. 284","y":1915,"id":"scdb/1914-169","sc":1,"op":5,"sum":"In an action to determine by what law the beneficiaries of a Creek allotment are to be determined where the allotment was selected by a Creek citizen and made by the Dawes Commission under § 11 of the Curtis Act of June 28, 1898, followed first by the death of the allottee after.receiving the allotment and prior to the Original Creek Agreement and then by action of the Commission, after ratification of that …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"6, 8, 27, 28","1":"9, 22, 37, 41","2":"7, 13, 20, 23"}},{"t":"usc","label":"18 U.S.C. § 1151","url":"https://www.law.cornell.edu/uscode/text/18/1151","subs":["(a)","(c)"],"stext":{"head":"§1151. Indian country defined","paras":[[0,"Except as otherwise provided in sections 1154 and 1156 of this title, the term \"Indian country\", as used in this chapter, means (a) all land within the limits of any Indian reservation under the jurisdiction of the United States Government, notwithstanding the issuance of any patent, and, including rights-of-way running through the reservation, (b) all dependent Indian communities within the borders of the United States whether within the original or subsequently acquired territory thereof, and whether within or without the limits of a state, and (c) all Indian allotments, the Indian titles to which have not been extinguished, including rights-of-way running through the same."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1151?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1151. Indian country defined","tname":"Crimes and Criminal Procedure","by":{"0":"45","1":"5","2":"36, 1, 37"}},{"t":"usc","label":"18 U.S.C. § 1152","url":"https://www.law.cornell.edu/uscode/text/18/1152","stext":{"head":"§1152. Laws governing","paras":[[0,"Except as otherwise expressly provided by law, the general laws of the United States as to the punishment of offenses committed in any place within the sole and exclusive jurisdiction of the United States, except the District of Columbia, shall extend to the Indian country."],[0,"This section shall not extend to offenses committed by one Indian against the person or property of another Indian, nor to any Indian committing any offense in the Indian country who has been punished by the local law of the tribe, or to any case where, by treaty stipulations, the exclusive jurisdiction over such offenses is or may be secured to the Indian tribes respectively."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1152?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1152. Laws governing","tname":"Crimes and Criminal Procedure","by":{"0":"45","2":"1, 2, 35"}},{"t":"usc","label":"18 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/18/1153","subs":["(a)"],"stext":{"head":"§1153. Offenses committed within Indian country","paras":[[0,"(a) Any Indian who commits against the person or property of another Indian or other person any of the following offenses, namely, murder, manslaughter, kidnapping, maiming, a felony under chapter 109A, incest, a felony assault under section 113, an assault against an individual who has not attained the age of 16 years, felony child abuse or neglect, arson, burglary, robbery, and a felony under section 661 of this title within the Indian country, shall be subject to the same law and penalties as all other persons committing any of the above offenses, within the exclusive jurisdiction of the United States."],[0,"(b) Any offense referred to in subsection (a) of this section that is not defined and punished by Federal law in force within the exclusive jurisdiction of the United States shall be defined and punished in accordance with the laws of the State in which such offense was committed as are in force at the time of such offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/1153?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1153. Offenses committed within Indian country","tname":"Crimes and Criminal Procedure","by":{"0":"42, 45","2":"2, 34"}},{"t":"usc","label":"25 U.S.C. § 5201","url":"https://www.law.cornell.edu/uscode/text/25/5201","stext":{"head":"§5201. Acquisition of agricultural and grazing lands for Indians; title to lands; tax exemption","paras":[[0,"The Secretary of the Interior is authorized, in his discretion, to acquire by purchase, relinquishment, gift, exchange, or assignment, any interest in lands, water rights, or surface rights to lands, within or without existing Indian reservations, including trust or otherwise restricted lands now in Indian ownership: Provided, That such lands shall be agricultural and grazing lands of good character and quality in proportion to the respective needs of the particular Indian or Indians for whom such purchases are made. Title to all lands so acquired shall be taken in the name of the United States, in trust for the tribe, band, group, or individual Indian for whose benefit such land is so acquired, and while the title thereto is held by the United States said lands shall be free from any and all taxes, save that the State of Oklahoma is authorized to levy and collect a gross-production tax, not in excess of the rate applied to production from lands in private ownership, upon all oil and gas produced from said lands, which said tax the Secretary of the Interior is authorized and directed to cause to be paid."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/5201?type=usc&year=mostrecent&link-type=html"},"head":"§5201. Acquisition of agricultural and grazing lands for Indians; title to lands; tax exemption","tname":"Indians","by":{"0":"42","2":"22"}},{"t":"law","label":"Pub. L. No. 83-280","url":"https://www.govinfo.gov/link/statute/67/588","by":{"0":"46"}},{"t":"law","label":"Safe, Accountable, Flexible, Efficient Transportation Equity Act, Pub. L. No. 109-59","url":"https://www.govinfo.gov/link/plaw/109/public/59","by":{"0":"42"}},{"t":"case","label":"Brief of Court-Appointed Amicus Curiae, Welch v. United States","cite":"2016 WL 891339","by":{"0":"42"}},{"t":"case","label":"Alaska v. Native Vill. of Venetie Tribal Gov’t","cite":"522 U.S. 520","y":1998,"id":"1997/96-1577","sc":1,"op":13,"ar":2,"sum":"The Court held that the Tribe's land is not \"Indian country.\" \"As noted, only one Indian reservation, the Annette Island Reserve, survived ANCSA,\" explained Justice Thomas in a footnote, [o]ther Indian country exists in Alaska post-ANCSA only if the land in question meets the requirements of a 'dependent Indian community' under our interpretation of [18 USC section 1151 (b)], or if it constitutes 'allotments' under [18 USC section 1151 (c)].\" \"The Tribe's ANCSA lands do not satisfy either of these requirements,\" concluded Justice Thomas, \"[a]fter the enactment of ANCSA, the Tribe's lands are neither 'validly set apart for the use of the Indians as such,' nor are they under the superintendence of the Federal Government.\".","sumSrc":"Oyez","by":{"1":"1, 5, 8, 11, 12, 14, 31","3":"7, 8"}},{"t":"case","label":"Atkinson Trading Co. v. Shirley","cite":"532 U.S. 645","y":2001,"id":"2000/00-454","sc":1,"sum":"The Court held that the Navajo Nation's imposition of a hotel occupancy tax upon nonmembers on non-Indian fee land within its reservation is invalid.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Bates v. Clark","cite":"95 U.S. 204","y":1877,"id":"scdb/1877-066","sc":1,"op":1,"by":{"1":"9, 18","3":"7"}},{"t":"case","label":"Bigfeather v. State","cite":"123 P. 1026","y":1912,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./123/1026/","op":1,"by":{"1":"17"}},{"t":"case","label":"Donnelly v. United States","cite":"228 U.S. 243","y":1913,"id":"scdb/1912-161","sc":1,"sum":"From an early period Congress has accorded to the Executive a large discretion about setting apart and reserving portions of the public domain in aid of particular public purposes.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15","3":"4, 5"}},{"t":"case","label":"Evans v. Victor","cite":"204 F. 361","y":1913,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./204/361/","by":{"1":"36"}},{"t":"case","label":"Grayson v. Harris","cite":"267 U.S. 352","y":1927,"id":"scdb/1924-105","sc":1,"op":2,"sum":"1. Judgment held reviewable by certiorari and not by writ of error. P. 353. <..","sumSrc":"Headnote (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Heckman v. United States","cite":"224 U.S. 413","y":1912,"id":"scdb/1911-217","sc":1,"sum":"The United States has capacity to maintain a suit to set aside conveyances made by allottee Indians of allotted lands within the statutory period of restriction; and this suit brought against numerous defendants, all of whom were grantees of allottees of the same tribe, is properly maintainable in equity; the return of the consideration to the grantee is not essential; there is no defect of parties because the …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"(V) Cases—Continued Hendrix v. United States","cite":"219 U.S. 79","y":1911,"id":"scdb/1910-050","sc":1,"sum":"The United States court at a particular place named is a sufficient designation of the only court of the United States held at that place, which has jurisdiction of the case; and an order transmitting a case under the act.of June 28, 1898, c. 517, 30 Stat. 511, to the United States court at Paris, Texas, is sufficient to transfer the case to the District Court of the United States for the Eastern District of Texas, …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"18","2":"33, 34"}},{"t":"case","label":"Higgins v. Brown","cite":"94 P. 703","y":1908,"court":"Okla.","url":"https://www.courtlistener.com/c/P./94/703/","op":1,"by":{"1":"17, 27"}},{"t":"case","label":"Hous. Auth. of Seminole Nation v. Harjo","cite":"790 P.2d 1098","y":1990,"court":"Okla.","url":"https://www.courtlistener.com/c/P.2d/790/1098/","by":{"1":"15"}},{"t":"case","label":"Hydro Res., Inc. v. EPA","cite":"608 F.3d 1131","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/608/1131/","ar":3,"by":{"1":"14","3":"7-8"}},{"t":"case","label":"Jefferson v. Fink","cite":"247 U.S. 288","y":1918,"id":"scdb/1917-139","sc":1,"op":1,"sum":"The policy and legislation of Congress respecting the descent of Indian allotments, particularly in the Five Civilized Tribes, reviewed.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"30, 35","2":"8, 19, 22"}},{"t":"case","label":"Lewellen v. United States","cite":"223 F. 18","y":1915,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F./223/18/","by":{"1":"19"}},{"t":"case","label":"Magnan v. Trammell","cite":"719 F.3d 1159","y":2013,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/1159/","by":{"1":"15"}},{"t":"case","label":"Marlin v. Lewallen","cite":"276 U.S. 58","y":1928,"id":"scdb/1927-089","sc":1,"op":2,"sum":"1. The surviving husband of a woman of the Creek blood and tribe, whether himself of that blood or not, has no estate of curtesy in land allotted and patented to her in the distribution of the tribal property under the original and supplemental Creek Agreements, Acts of March 1, 1901, and June 30, 1902, and of which she died seized, intestate and leaving issue. Pp. 59, 68.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"22, 24","2":"9, 13, 29"}},{"t":"case","label":"Maxey v. Wright","cite":"54 S.W. 807","y":1900,"court":"Ct. App. Indian Terr.","url":"https://www.courtlistener.com/c/S.W./54/807/","op":1,"by":{"1":"13","3":"6"}},{"t":"case","label":"McClanahan v. State Tax Comm’n of Ariz.","cite":"411 U.S. 164","y":1973,"id":"1972/71-834","sc":1,"op":1,"sum":"The Court reversed the decision of the Arizona Court of Appeals and held that Arizona did not have the right to tax McClanahan. In an opinion authored by Justice Thurgood Marshall, the Court emphasized the long-standing status of Indian reservations as exempt from state authority.","sumSrc":"Oyez","by":{"1":"41","2":"40"}},{"t":"case","label":"Menominee Tribe v. United States","cite":"391 U.S. 404","y":1968,"id":"1967/187","sc":1,"op":1,"sum":"The Menominee Tribe of Indians brought this action in the Court of Claims to recover compensation for the loss of their hunting and fishing rights, which the Wisconsin Supreme Court in another proceeding had held had been abrogated by the Menominee Termination Act of 1954. The Termination Act, which did not become fully effective until 1961, provided for the termination of federal supervision over the property and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Miss. Band of Choctaw Indians v. Holyfield","cite":"490 U.S. 30","y":1989,"id":"1988/87-980","sc":1,"sum":"The twins were \"domiciled\" on the Tribe's reservation within the meaning of the ICWA's exclusive tribal jurisdiction provision, and the Chancery Court was, accordingly, without jurisdiction to enter the adoption decree.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Norwegian Nitrogen Prods. Co. v. United States","cite":"288 U.S. 294","y":1933,"id":"scdb/1932-150","sc":1,"sum":"The Tariff Act of 1922 empowers the President to change rates of duty in order to equalize differences in costs of production in this country and abroad, but provides--§ 315 (c)-that before he acts there shall have been an investigation of such differences by the Tariff Commission, in the making of which the Commission shall give reasonable public notice of its hearings, and shall give \"reasonable opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Okla. Tax Comm’n v. Sac & Fox Nation","cite":"508 U.S. 114","y":1993,"id":"1992/92-259","sc":1,"sum":"Respondent Sac and Fox Nation (Tribe) is a federally recognized Indian tribe located in Oklahoma. It brought this action seeking a permanent injunction barring petitioner Oklahoma Tax Commission (Commission) from, among other things, taxing the income of tribal members who work or reside within tribal jurisdiction, and imposing the State's motor vehicle excise tax and registration fees on tribal members who live and …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Okla. Tax Comm’n v. United States","cite":"319 U.S. 598","y":1943,"id":"scdb/1942-059","sc":1,"by":{"1":"24, 41","2":"24"}},{"t":"case","label":"Organized Village of Kake v. Egan","cite":"369 U.S. 60","y":1962,"id":"1961/3","sc":1,"sum":"The Supreme Court held that there was no statutory authority granting the Secretary of the Interior the power to regulate contrary to state law. In addition, the permits did not trump state law. In order to prevent undue hardship, the Court ordered that the Native American tribes be allowed to continue using the traps through the end of the 1962 fishing season.","sumSrc":"Oyez","by":{"1":"34","3":"16"}},{"t":"case","label":"Osage Nation v. Irby","cite":"597 F.3d 1117","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/597/1117/","by":{"1":"40"}},{"t":"case","label":"Pickett v. United States","cite":"216 U.S. 456","y":1910,"id":"scdb/1909-099","sc":1,"sum":"On the organization of a Territory into a State, Congress may — as it did by the Oklahoma enabling act- — transfer the jurisdiction of general crimes committed in districts over which the United States retains exclusive jurisdiction from territorial to Federal.courts, and may extend such jurisdiction to crimes' committed before and after the enabling act. See United States v. Brown, 74 Fed. Rep. 43.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Sizemore v. Brady","cite":"235 U.S. 441","y":1914,"id":"scdb/1914-037","sc":1,"sum":"The Original Creek Agreement of March 1, 1901, was not a grant in prossenti which invested the then living members.of the tribe and their heirs with absolute rights that could not be recalled or impaired by Congress without violating the due process clause of the Fifth Amendment,","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Stephens v. Cherokee Nation","cite":"174 U.S. 445","y":1899,"id":"scdb/1898-156","sc":1,"sum":"Congress may provide for a review of the action of commissioners and boards created by it and exercising only quasi judicial powers, by a transfer of their proceedings and decisions to judicial tribunals for examination and determination de novo.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"35","2":"8"}},{"t":"case","label":"Swafford v. United States","cite":"25 F.2d 581","y":1928,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/25/581/","by":{"1":"19"}},{"t":"case","label":"Tiger v. Western Investment Co.","cite":"221 U.S. 286","y":1911,"id":"scdb/1910-140","sc":1,"op":1,"sum":"The obvious purpose of § 8 of the act of May 27,1908, c. 199, 35 Stat. 312, was to continue supervision over the right of full-blood Indians i to dispose of lands by will, and to require conveyances of interests of full-blood Indians in inherited lands to be approved by a compe- tent court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"20, 34"}},{"t":"case","label":"United States v. Adair","cite":"913 F. Supp. 1503","y":1995,"court":"E.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./913/1503/","by":{"1":"16"}},{"t":"case","label":"United States v. Allen","cite":"171 F. 907","y":1909,"court":"E.D. Okla.","url":"https://www.courtlistener.com/c/F./171/907/","by":{"1":"38"}},{"t":"case","label":"United States v. Celestine","cite":"215 U.S. 278","y":1909,"id":"scdb/1909-032","sc":1,"op":3,"sum":"Although an Indian may be made a citizen of the United States.ándof the State in which the reservation for his tribe is. located, the United States may still retain jurisdiction over him for offenses committed within the limits of the reservation; and so held as to a crime committed by an Indian against another Indian on the Tulalip Indian Reservation in Washington, notwithstanding the Indians had received …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16, 20","3":"4, 16"}},{"t":"case","label":"United States v. Creek Nation","cite":"295 U.S. 103","y":1935,"id":"scdb/1934-113","sc":1,"op":4,"sum":"Counsel for Parties. (1) That the claim of the Creek Tribe for compensation was a claim \"arising under or growing out of\" a \"treaty or agreement\" between the United States and that Tribe, or \"arising under or growing out of\" an \"Act of Congress in relation to Indian Affairs,\"/-within the meaning of the Act of May 24, 1924, conferring jurisdiction on the Court of Claims to adjudicate. P. 108. (2) The lands were …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"11, 12","2":"8","3":"9"}},{"t":"case","label":"United States v. McGowan","cite":"302 U.S. 535","y":1938,"id":"scdb/1937-152","sc":1,"ar":1,"sum":"\"Indian country\" within the meaning of 25 U. S. C. § 247, subjecting to forfeiture automobiles and other vehiclei uied in taking intoxicants into the \"Indian country.\" P. 53§.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13","3":"8"}},{"t":"case","label":"United States v. Sandoval","cite":"231 U.S. 28","y":1913,"id":"scdb/1913-059","sc":1,"op":5,"ar":7,"sum":"Congress has power to make conditions in an Enabling Act, and require the State to assent thereto, as to such subjects as are within the regulating power of Congress. Coyle v. Oklahoma, 221 U. S. 559, 574.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"11, 12, 13","2":"8","3":"8, 9"}},{"t":"case","label":"Washington v. Miller","cite":"235 U.S. 422","y":1914,"id":"scdb/1914-047","sc":1,"op":2,"sum":"Under the original Creek Agreement of March 1, 1901, controlling effect was given to the Creek tribal laws of descent, and distribution rather than to the laws of Arkansas upon that subject put in force in tbe Indian Territory, and the provisions giving such effect to the tribal laws embraced allotments to living citizens as well as allotments on behalf of deceased citizens.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"31, 41","2":"23"}},{"t":"usc","label":"6 U.S.C. § 601","url":"https://www.law.cornell.edu/uscode/text/6/601","stext":{"head":"§601. Definitions","paras":[[0,"In this subchapter, the following definitions shall apply:"],[0,"(1) Administrator"],[1,"The term \"Administrator\" means the Administrator of the Federal Emergency Management Agency."],[0,"(2) Appropriate committees of Congress"],[1,"The term \"appropriate committees of Congress\" means—"],[2,"(A) the Committee on Homeland Security and Governmental Affairs of the Senate; and"],[2,"(B) those committees of the House of Representatives that the Speaker of the House of Representatives determines appropriate."],[0,"(3) Critical infrastructure sectors"],[1,"The term \"critical infrastructure sectors\" means the following sectors, in both urban and rural areas:"],[2,"(A) Agriculture and food."],[2,"(B) Banking and finance."],[2,"(C) Chemical industries."],[2,"(D) Commercial facilities."],[2,"(E) Commercial nuclear reactors, materials, and waste."],[2,"(F) Dams."],[2,"(G) The defense industrial base."],[2,"(H) Emergency services."],[2,"(I) Energy."],[2,"(J) Government facilities."],[2,"(K) Information technology."],[2,"(L) National monuments and icons."],[2,"(M) Postal and shipping."],[2,"(N) Public health and health care."],[2,"(O) Telecommunications."],[2,"(P) Transportation systems."],[2,"(Q) Water."],[0,"(4) Directly eligible tribe"],[1,"The term \"directly eligible tribe\" means—"],[2,"(A) any Indian tribe—"],[3,"(i) that is located in the continental United States;"],[3,"(ii) that operates a law enforcement or emergency response agency with the capacity to respond to calls for law enforcement or emergency services;"],[3,"(iii)(I) that is located on or near an international border or a coastline bordering an ocean (including the Gulf of Mexico) or international waters;"],[3,"(II) that is located within 10 miles of a system or asset included on the prioritized critical infrastructure list established under section 664(a)(2) of this title or has such a system or asset within its territory;"],[3,"(III) that is located within or contiguous to 1 of the 50 most populous metropolitan statistical areas in the United States; or"],[3,"(IV) the jurisdiction of which includes not less than 1,000 square miles of Indian country, as that term is defined in section 1151 of title 18; and"],[3,"(iv) that certifies to the Secretary that a State has not provided funds under section 604 or 605 of this title to the Indian tribe or consortium of Indian tribes for the purpose for which direct funding is sought; and"],[2,"(B) a consortium of Indian tribes, if each tribe satisfies the requirements of subparagraph (A)."],[0,"(5) Eligible metropolitan area"],[1,"The term \"eligible metropolitan area\" means any of the 100 most populous metropolitan statistical areas in the United States."],[0,"(6) High-risk urban area"],[1,"The term \"high-risk urban area\" means a high-risk urban area designated under section 604(b)(3)(A) of this title."],[0,"(7) Indian tribe"],[1,"The term \"Indian tribe\" has the meaning given that term in section 5304(e) of title 25."],[0,"(8) Metropolitan statistical area"],[1,"The term \"metropolitan statistical area\" means a metropolitan statistical area, as defined by the Office of Management and Budget."],[0,"(9) National Special Security Event"],[1,"The term \"National Special Security Event\" means a designated event that, by virtue of its political, economic, social, or religious significance, may be the target of terrorism or other criminal activity."],[0,"(10) Population"],[1,"The term \"population\" means population according to the most recent United States census population estimates available at the start of the relevant fiscal year."],[0,"(11) Population density"],[1,"The term \"population density\" means population divided by land area in square miles."],[0,"(12) Qualified intelligence analyst"],[1,"The term \"qualified intelligence analyst\" means an intelligence analyst (as that term is defined in section 124h(j) of this title), including law enforcement personnel—"],[2,"(A) who has successfully completed training to ensure baseline proficiency in intelligence analysis and production, as determined by the Secretary, which may include training using a curriculum developed under section 124f of this title; or"],[2,"(B) whose experience ensures baseline proficiency in intelligence analysis and production equivalent to the training required under subparagraph (A), as determined by the Secretary."],[0,"(13) Target capabilities"],[1,"The term \"target capabilities\" means the target capabilities for Federal, State, local, and tribal government preparedness for which guidelines are required to be established under section 746(a) of this title."],[0,"(14) Tribal government"],[1,"The term \"tribal government\" means the government of an Indian tribe."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/6/601?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§601. Definitions","tname":"Domestic Security","by":{"1":"43"}},{"t":"usc","label":"7 U.S.C. § 2012","url":"https://www.law.cornell.edu/uscode/text/7/2012","stext":{"head":"§2012. Definitions","paras":[[0,"As used in this chapter, the term:"],[0,"(a) \"Access device\" means any card, plate, code, account number, or other means of access, including point of sale devices, that can be used, alone or in conjunction with another access device, to obtain payments, allotments, benefits, money, goods, or other things of value, or that can be used to initiate a transfer of funds under this chapter."],[0,"(b) \"Allotment\" means the total value of benefits a household is authorized to receive during each month."],[0,"(c) \"Allowable medical expenses\" means expenditures for (1) medical and dental care, (2) hospitalization or nursing care (including hospitalization or nursing care of an individual who was a household member immediately prior to entering a hospital or nursing home), (3) prescription drugs when prescribed by a licensed practitioner authorized under State law and over-the-counter medication (including insulin) when approved by a licensed practitioner or other qualified health professional, (4) health and hospitalization insurance policies (excluding the costs of health and accident or income maintenance policies), (5) medicare premiums related to coverage under title XVIII of the Social Security Act [42 U.S.C. 1395 et seq.], (6) dentures, hearing aids, and prosthetics (including the costs of securing and maintaining a seeing eye dog), (7) eye glasses prescribed by a physician skilled in eye disease or by an optometrist, (8) reasonable costs of transportation necessary to secure medical treatment or services, and (9) maintaining an attendant, homemaker, home health aide, housekeeper, or child care services due to age, infirmity, or illness."],[0,"(d) Benefit.—The term \"benefit\" means the value of supplemental nutrition assistance provided to a household by means of—"],[1,"(1) an electronic benefit transfer under section 2016(h) of this title; or"],[1,"(2) other means of providing assistance, as determined by the Secretary."],[0,"(e) Benefit Issuer.—The term \"benefit issuer\" means any office of the State agency or any person, partnership, corporation, organization, political subdivision, or other entity with which a State agency has contracted for, or to which it has delegated functional responsibility in connection with, the issuance of benefits to households."],[0,"(f) \"Certification period\" means the period for which households shall be eligible to receive benefits. The certification period shall not exceed 12 months, except that the certification period may be up to 24 months if all adult household members are elderly or disabled. A State agency shall have at least 1 contact with each certified household every 12 months. The limits specified in this subsection may be extended until the end of any transitional benefit period established under section 2020(s) of this title."],[0,"(g) \"Coupon\" means any coupon, stamp, type of certificate, authorization card, cash or check issued in lieu of a coupon."],[0,"(h) \"Drug addiction or alcoholic treatment and rehabilitation program\" means any such program conducted by a private nonprofit organization or institution, or a publicly operated community mental health center, under part B of title XIX of the Public Health Service Act (42 U.S.C. 300x et seq.) to provide treatment that can lead to the rehabilitation of drug addicts or alcoholics."],[0,"(i) EBT Card.—The term \"EBT card\" means an electronic benefit transfer card issued under section 2016(h) of this title."],[0,"(j) \"Elderly or disabled member\" means a member of a household who—"],[1,"(1) is sixty years of age or older;"],[1,"(2)(A) receives supplemental security income benefits under title XVI of the Social Security Act (42 U.S.C. 1381 et seq.), or Federally or State administered supplemental benefits of the type described in section 212(a) of Public Law 93–66 (42 U.S.C. 1382 note), or"],[1,"(B) receives Federally or State administered supplemental assistance of the type described in section 1616(a) of the Social Security Act (42 U.S.C. 1382e(a)), interim assistance pending receipt of supplemental security income, disability-related medical assistance under title XIX of the Social Security Act (42 U.S.C. 1396 et seq.), or disability-based State general assistance benefits, if the Secretary determines that such benefits are conditioned on meeting disability or blindness criteria at least as stringent as those used under title XVI of the Social Security Act;"],[1,"(3) receives disability or blindness payments under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.] or receives disability retirement benefits from a governmental agency because of a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i));"],[1,"(4) is a veteran who—"],[2,"(A) has a service-connected or non-service-connected disability which is rated as total under title 38; or"],[2,"(B) is considered in need of regular aid and attendance or permanently housebound under such title;"],[1,"(5) is a surviving spouse of a veteran and—"],[2,"(A) is considered in need of regular aid and attendance or permanently housebound under title 38; or"],[2,"(B) is entitled to compensation for a service-connected death or pension benefits for a non-service-connected death under title 38, and has a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i));"],[1,"(6) is a child of a veteran and—"],[2,"(A) is considered permanently incapable of self-support under section 1314 of title 38; or"],[2,"(B) is entitled to compensation for a service-connected death or pension benefits for a non-service-connected death under title 38, and has a disability considered permanent under section 221(i) of the Social Security Act (42 U.S.C. 421(i)); or"],[1,"(7) is an individual receiving an annuity under section 2(a)(1)(iv) or 2(a)(1)(v) of the Railroad Retirement Act of 1974 (45 U.S.C. 231a(a)(1)(iv) or 231a(a)(1)(v)), if the individual's service as an employee under the Railroad Retirement Act of 1974 [45 U.S.C. 231 et seq.], after December 31, 1936, had been included in the term \"employment\" as defined in the Social Security Act [42 U.S.C. 301 et seq.], and if an application for disability benefits had been filed."],[0,"(k) \"Food\" means (1) any food or food product for home consumption except alcoholic beverages, tobacco, hot foods or hot food products ready for immediate consumption other than those authorized pursuant to clauses (3), (4), (5), (7), (8), and (9) of this subsection, and any deposit fee in excess of the amount of the State fee reimbursement (if any) required to purchase any food or food product contained in a returnable bottle or can, regardless of whether the fee is included in the shelf price posted for the food or food product, (2) seeds and plants for use in gardens to produce food for the personal consumption of the eligible household, (3) in the case of those persons who are sixty years of age or over or who receive supplemental security income benefits or disability or blindness payments under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.], and their spouses, meals prepared by and served in senior citizens' centers, apartment buildings occupied primarily by such persons, public or private nonprofit establishments (eating or otherwise) that feed such persons, private establishments that contract with the appropriate agency of the State to offer meals for such persons at concessional prices subject to section 2018(h) of this title, and meals prepared for and served to residents of federally subsidized housing for the elderly, (4) in the case of persons sixty years of age or over and persons who are physically or mentally handicapped or otherwise so disabled that they are unable adequately to prepare all of their meals, meals prepared for and delivered to them (and their spouses) at their home by a public or private nonprofit organization or by a private establishment that contracts with the appropriate State agency to perform such services at concessional prices subject to section 2018(h) of this title, (5) in the case of narcotics addicts or alcoholics, and their children, served by drug addiction or alcoholic treatment and rehabilitation programs, meals prepared and served under such programs, (6) in the case of certain eligible households living in Alaska, equipment for procuring food by hunting and fishing, such as nets, hooks, rods, harpoons, and knives (but not equipment for purposes of transportation, clothing, or shelter, and not firearms, ammunition, and explosives) if the Secretary determines that such households are located in an area of the State where it is extremely difficult to reach stores selling food and that such households depend to a substantial extent upon hunting and fishing for subsistence, (7) in the case of disabled or blind recipients of benefits under title I, II, X, XIV, or XVI of the Social Security Act [42 U.S.C. 301 et seq., 401 et seq., 1201 et seq., 1351 et seq., 1381 et seq.], and individuals described in paragraphs (2) through (7) of subsection (j), who are residents in a public or private nonprofit group living arrangement that serves no more than sixteen residents and is certified by the appropriate State agency or agencies under regulations issued under section 1616(e) of the Social Security Act [42 U.S.C. 1382e(e)] or under standards determined by the Secretary to be comparable to standards implemented by appropriate State agencies under such section, meals prepared and served under such arrangement, (8) in the case of women and children temporarily residing in public or private nonprofit shelters for battered women and children, meals prepared and served, by such shelters, and (9) in the case of households that do not reside in permanent dwellings and households that have no fixed mailing addresses, meals prepared for and served by a public or private nonprofit establishment (approved by an appropriate State or local agency) that feeds such individuals and by private establishments that contract with the appropriate agency of the State to offer meals for such individuals at concessional prices subject to section 2018(h) of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/2012?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2012. Definitions","tname":"Agriculture","by":{"1":"43"}},{"t":"usc","label":"10 U.S.C. § 284","url":"https://www.law.cornell.edu/uscode/text/10/284","by":{"1":"43"}},{"t":"usc","label":"15 U.S.C. § 376","url":"https://www.law.cornell.edu/uscode/text/15/376","subs":["(a)(3)"],"by":{"1":"43"}},{"t":"usc","label":"16 U.S.C. § 594","url":"https://www.law.cornell.edu/uscode/text/16/594","by":{"1":"44"}},{"t":"usc","label":"20 U.S.C. § 1411","url":"https://www.law.cornell.edu/uscode/text/20/1411","stext":{"head":"§1411. Authorization; allotment; use of funds; authorization of appropriations","paras":[[0,"(a) Grants to States"],[0,"(1) Purpose of grants"],[1,"The Secretary shall make grants to States, outlying areas, and freely associated States, and provide funds to the Secretary of the Interior, to assist them to provide special education and related services to children with disabilities in accordance with this subchapter."],[0,"(2) Maximum amount"],[1,"The maximum amount of the grant a State may receive under this section—"],[2,"(A) for fiscal years 2005 and 2006 is—"],[3,"(i) the number of children with disabilities in the State who are receiving special education and related services—"],[4,"(I) aged 3 through 5 if the State is eligible for a grant under section 1419 of this title; and"],[4,"(II) aged 6 through 21; multiplied by"],[3,"(ii) 40 percent of the average per-pupil expenditure in public elementary schools and secondary schools in the United States; and"],[2,"(B) for fiscal year 2007 and subsequent fiscal years is—"],[3,"(i) the number of children with disabilities in the 2004–2005 school year in the State who received special education and related services—"],[4,"(I) aged 3 through 5 if the State is eligible for a grant under section 1419 of this title; and"],[4,"(II) aged 6 through 21; multiplied by"],[3,"(ii) 40 percent of the average per-pupil expenditure in public elementary schools and secondary schools in the United States; adjusted by"],[3,"(iii) the rate of annual change in the sum of—"],[4,"(I) 85 percent of such State's population described in subsection (d)(3)(A)(i)(II); and"],[4,"(II) 15 percent of such State's population described in subsection (d)(3)(A)(i)(III)."],[0,"(b) Outlying areas and freely associated States; Secretary of the Interior"],[0,"(1) Outlying areas and freely associated States"],[0,"(A) Funds reserved"],[2,"From the amount appropriated for any fiscal year under subsection (i), the Secretary shall reserve not more than 1 percent, which shall be used as follows:"],[3,"(i) To provide assistance to the outlying areas in accordance with their respective populations of individuals aged 3 through 21."],[3,"(ii)(I) To provide each freely associated State a grant so that no freely associated State receives a lesser share of the total funds reserved for the freely associated State than the freely associated State received of those funds for fiscal year 2023."],[3,"(II) Each freely associated State shall establish its eligibility under this subparagraph consistent with the requirements for a State under section 1412 of this title."],[3,"(III) The funds provided to each freely associated State under this subchapter may be used to provide, to each infant or toddler with a disability (as defined in section 1432 of this title), either a free appropriate public education, consistent with section 1412 of this title, or early intervention services consistent with subchapter III, notwithstanding the application and eligibility requirements of sections 1431(2), 1435, and 1437 of this title."],[0,"(B) Special rule"],[2,"The provisions of Public Law 95–134, permitting the consolidation of grants by the outlying areas, shall not apply to funds provided to the outlying areas or the freely associated States under this section."],[0,"(C) Definition"],[2,"In this paragraph, the term \"freely associated States\" means the Republic of the Marshall Islands, the Federated States of Micronesia, and the Republic of Palau."],[0,"(2) Secretary of the Interior"],[1,"From the amount appropriated for any fiscal year under subsection (i), the Secretary shall reserve 1.226 percent to provide assistance to the Secretary of the Interior in accordance with subsection (h)."],[0,"(c) Technical assistance"],[0,"(1) In general"],[1,"The Secretary may reserve not more than ½ of 1 percent of the amounts appropriated under this subchapter for each fiscal year to provide technical assistance activities authorized under section 1416(i) of this title."],[0,"(2) Maximum amount"],[1,"The maximum amount the Secretary may reserve under paragraph (1) for any fiscal year is $25,000,000, cumulatively adjusted by the rate of inflation as measured by the percentage increase, if any, from the preceding fiscal year in the Consumer Price Index For All Urban Consumers, published by the Bureau of Labor Statistics of the Department of Labor."],[0,"(d) Allocations to States"],[0,"(1) In general"],[1,"After reserving funds for technical assistance, and for payments to the outlying areas, the freely associated States, and the Secretary of the Interior under subsections (b) and (c) for a fiscal year, the Secretary shall allocate the remaining amount among the States in accordance with this subsection."],[0,"(2) Special rule for use of fiscal year 1999 amount"],[1,"If a State received any funds under this section for fiscal year 1999 on the basis of children aged 3 through 5, but does not make a free appropriate public education available to all children with disabilities aged 3 through 5 in the State in any subsequent fiscal year, the Secretary shall compute the State's amount for fiscal year 1999, solely for the purpose of calculating the State's allocation in that subsequent year under paragraph (3) or (4), by subtracting the amount allocated to the State for fiscal year 1999 on the basis of those children."],[0,"(3) Increase in funds"],[1,"If the amount available for allocations to States under paragraph (1) for a fiscal year is equal to or greater than the amount allocated to the States under this paragraph for the preceding fiscal year, those allocations shall be calculated as follows:"],[0,"(A) Allocation of increase"],[0,"(i) In general"],[3,"Except as provided in subparagraph (B), the Secretary shall allocate for the fiscal year—"],[4,"(I) to each State the amount the State received under this section for fiscal year 1999;"],[4,"(II) 85 percent of any remaining funds to States on the basis of the States' relative populations of children aged 3 through 21 who are of the same age as children with disabilities for whom the State ensures the availability of a free appropriate public education under this subchapter; and"],[4,"(III) 15 percent of those remaining funds to States on the basis of the States' relative populations of children described in subclause (II) who are living in poverty."],[0,"(ii) Data"],[3,"For the purpose of making grants under this paragraph, the Secretary shall use the most recent population data, including data on children living in poverty, that are available and satisfactory to the Secretary."],[0,"(B) Limitations"],[2,"Notwithstanding subparagraph (A), allocations under this paragraph shall be subject to the following:"],[0,"(i) Preceding year allocation"],[3,"No State's allocation shall be less than its allocation under this section for the preceding fiscal year."],[0,"(ii) Minimum"],[3,"No State's allocation shall be less than the greatest of—"],[4,"(I) the sum of—"],[5,"(aa) the amount the State received under this section for fiscal year 1999; and"],[5,"(bb) 1/3 of 1 percent of the amount by which the amount appropriated under subsection (i) for the fiscal year exceeds the amount appropriated for this section for fiscal year 1999;"],[4,"(II) the sum of—"],[5,"(aa) the amount the State received under this section for the preceding fiscal year; and"],[5,"(bb) that amount multiplied by the percentage by which the increase in the funds appropriated for this section from the preceding fiscal year exceeds 1.5 percent; or"],[4,"(III) the sum of—"],[5,"(aa) the amount the State received under this section for the preceding fiscal year; and"],[5,"(bb) that amount multiplied by 90 percent of the percentage increase in the amount appropriated for this section from the preceding fiscal year."],[0,"(iii) Maximum"],[3,"Notwithstanding clause (ii), no State's allocation under this paragraph shall exceed the sum of—"],[4,"(I) the amount the State received under this section for the preceding fiscal year; and"],[4,"(II) that amount multiplied by the sum of 1.5 percent and the percentage increase in the amount appropriated under this section from the preceding fiscal year."],[0,"(C) Ratable reduction"],[2,"If the amount available for allocations under this paragraph is insufficient to pay those allocations in full, those allocations shall be ratably reduced, subject to subparagraph (B)(i)."],[0,"(4) Decrease in funds"],[1,"If the amount available for allocations to States under paragraph (1) for a fiscal year is less than the amount allocated to the States under this section for the preceding fiscal year, those allocations shall be calculated as follows:"],[0,"(A) Amounts greater than fiscal year 1999 allocations"],[2,"If the amount available for allocations is greater than the amount allocated to the States for fiscal year 1999, each State shall be allocated the sum of—"],[3,"(i) the amount the State received under this section for fiscal year 1999; and"],[3,"(ii) an amount that bears the same relation to any remaining funds as the increase the State received under this section for the preceding fiscal year over fiscal year 1999 bears to the total of all such increases for all States."],[0,"(B) Amounts equal to or less than fiscal year 1999 allocations"],[0,"(i) In general"],[3,"If the amount available for allocations under this paragraph is equal to or less than the amount allocated to the States for fiscal year 1999, each State shall be allocated the amount the State received for fiscal year 1999."],[0,"(ii) Ratable reduction"],[3,"If the amount available for allocations under this paragraph is insufficient to make the allocations described in clause (i), those allocations shall be ratably reduced."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/20/1411?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1411. Authorization; allotment; use of funds; authorization of appropriations","tname":"Education","by":{"1":"44"}},{"t":"usc","label":"23 U.S.C. § 120","url":"https://www.law.cornell.edu/uscode/text/23/120","stext":{"head":"§120. Federal share payable","paras":[[0,"(a) Interstate System Projects.—"],[1,"(1) In general.—Except as otherwise provided in this chapter, the Federal share payable on account of any project on the Interstate System (including a project to add high occupancy vehicle lanes and a project to add auxiliary lanes but excluding a project to add any other lanes) shall be 90 percent of the total cost thereof, plus a percentage of the remaining 10 percent of such cost in any State containing unappropriated and unreserved public lands and nontaxable Indian lands, individual and tribal, exceeding 5 percent of the total area of all lands therein, equal to the percentage that the area of such lands in such State is of its total area; except that such Federal share payable on any project in any State shall not exceed 95 percent of the total cost of such project."],[1,"(2) State-determined lower federal share.—In the case of any project subject to paragraph (1), a State may determine a lower Federal share than the Federal share determined under such paragraph."],[0,"(b) Other Projects.—Except as otherwise provided in this title, the Federal share payable on account of any project or activity carried out under this title (other than a project subject to subsection (a)) shall be—"],[1,"(1) 80 percent of the cost thereof, except that in the case of any State containing nontaxable Indian lands, individual and tribal, and public domain lands (both reserved and unreserved) exclusive of national forests and national parks and monuments, exceeding 5 percent of the total area of all lands therein, the Federal share, for purposes of this chapter, shall be increased by a percentage of the remaining cost equal to the percentage that the area of all such lands in such State, is of its total area; or"],[1,"(2) 80 percent of the cost thereof, except that in the case of any State containing nontaxable Indian lands, individual and tribal, public domain lands (both reserved and unreserved), national forests, and national parks and monuments, the Federal share, for purposes of this chapter, shall be increased by a percentage of the remaining cost equal to the percentage that the area of all such lands in such State is of its total area;"],[0,"except that the Federal share payable on any project in a State shall not exceed 95 percent of the total cost of any such project. In any case where a State elects to have the Federal share provided in paragraph (2) of this subsection, the State must enter into an agreement with the Secretary covering a period of not less than 1 year, requiring such State to use solely for purposes eligible for assistance under this title (other than paying its share of projects approved under this title) during the period covered by such agreement the difference between the State's share as provided in paragraph (2) and what its share would be if it elected to pay the share provided in paragraph (1) for all projects subject to such agreement. In the case of any project subject to this subsection, a State may determine a lower Federal share than the Federal share determined under the preceding sentences of this subsection."],[0,"(c) Increased Federal Share.—"],[1,"(1) Certain safety projects.—The Federal share payable on account of any project for traffic control signalization, maintaining minimum levels of retroreflectivity of highway signs or pavement markings, traffic circles (also known as \"roundabouts\"), safety rest areas, pavement marking, shoulder and centerline rumble strips and stripes, commuter carpooling and vanpooling, rail-highway crossing closure, or installation of traffic signs, traffic lights, guardrails, impact attenuators, concrete barrier endtreatments, breakaway utility poles, vehicle-to-infrastructure communication equipment, or priority control systems for emergency vehicles or transit vehicles at signalized intersections may amount to 100 percent of the cost of construction of such projects; except that not more than 10 percent of all sums apportioned for all the Federal-aid programs for any fiscal year in accordance with section 104 of this title shall be used under this subsection. In this subsection, the term \"safety rest area\" means an area where motor vehicle operators can park their vehicles and rest, where food, fuel, and lodging services are not available, and that is located on a segment of highway with respect to which the Secretary determines there is a shortage of public and private areas at which motor vehicle operators can park their vehicles and rest."],[1,"(2) CMAQ projects.—The Federal share payable on account of a project or program carried out under section 149 with funds obligated in fiscal year 2008 or 2009, or both, shall be not less than 80 percent and, at the discretion of the State, may be up to 100 percent of the cost thereof."],[1,"(3) Innovative project delivery.—"],[2,"(A) In general.—Except as provided in subparagraph (C), the Federal share payable on account of a project, program, or activity carried out with funds apportioned under paragraph (1), (2), (5)(D), or (6) of section 104(b) may, at the discretion of the State, be up to 100 percent for any such project, program, or activity that the Secretary determines—"],[3,"(i) contains innovative project delivery methods that improve work zone safety for motorists or workers and the quality of the facility;"],[3,"(ii) contains innovative technologies, engineering or design approaches, manufacturing processes, financing, or contracting or project delivery methods that improve the quality of, extend the service life of, or decrease the long-term costs of maintaining highways and bridges;"],[3,"(iii) accelerates project delivery while complying with other applicable Federal laws (including regulations) and not causing any significant adverse environmental impact; or"],[3,"(iv) reduces congestion related to highway construction."],[2,"(B) Examples.—Projects, programs, and activities described in subparagraph (A) may include the use of—"],[3,"(i) prefabricated bridge elements and systems and other technologies to reduce bridge construction time;"],[3,"(ii) innovative construction equipment, materials, or techniques, including the use of in-place recycling technology and digital 3-dimensional modeling technologies;"],[3,"(iii) innovative contracting methods, including the design-build and the construction manager-general contractor contracting methods and alternative bidding;"],[3,"(iv) intelligent compaction equipment;"],[3,"(v) innovative pavement materials that have a demonstrated life cycle of 75 or more years, are manufactured with reduced greenhouse gas emissions, and reduce construction-related congestion by rapidly curing;"],[3,"(vi) contractual provisions that provide safety contingency funds to incorporate safety enhancements to work zones prior to or during roadway construction activities; or"],[3,"(vii) contractual provisions that offer a contractor an incentive payment for early completion of the project, program, or activity, subject to the condition that the incentives are accounted for in the financial plan of the project, when applicable."],[2,"(C) Limitations.—"],[3,"(i) In general.—In each fiscal year, a State may use the authority under subparagraph (A) for up to 10 percent of the combined apportionments of the State under paragraphs (1), (2), (5)(D), and (6) of section 104(b)."],[3,"(ii) Federal share increase.—The Federal share payable on account of a project, program, or activity described in subparagraph (A) may be increased by up to 5 percent of the total project cost."],[1,"(4) Pooled funding.—Notwithstanding any other provision of law, the Secretary may waive the non-Federal share of the cost of a project or activity under section 502(b)(6) that is carried out with amounts apportioned under section 104(b)(2) after considering appropriate factors, including whether—"],[2,"(A) decreasing or eliminating the non-Federal share would best serve the interests of the Federal-aid highway program; and"],[2,"(B) the project or activity addresses national or regional high priority research, development, and technology transfer problems in a manner that would benefit multiple States or metropolitan planning organizations."],[0,"(d) The Secretary may rely on a statement from the Secretary of the Interior as to the area of the lands referred to in subsections (a) and (b) of this section. The Secretary of the Interior is authorized and directed to provide such statement annually."],[0,"(e) Emergency Relief.—The Federal share payable for any repair or reconstruction provided for by funds made available under section 125 for any project on a Federal-aid highway, including the Interstate System, shall not exceed the Federal share payable on a project on the system as provided in subsections (a) and (b), except that—"],[1,"(1) the Federal share payable for eligible emergency repairs to minimize damage, protect facilities, or restore essential traffic accomplished within 270 days after the actual occurrence of the natural disaster or catastrophic failure may amount to 100 percent of the cost of the repairs;"],[1,"(2) the Federal share payable for any repair or reconstruction of Federal land transportation facilities, other Federally owned roads that are open to public travel, and tribal transportation facilities may amount to 100 percent of the cost of the repair or reconstruction;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/23/120?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§120. Federal share payable","tname":"Highways","by":{"1":"44"}},{"t":"usc","label":"25 U.S.C. § 162a","url":"https://www.law.cornell.edu/uscode/text/25/162a","subs":["(d)(8)"],"by":{"1":"44"}},{"t":"usc","label":"42 U.S.C. § 1769d","url":"https://www.law.cornell.edu/uscode/text/42/1769d","by":{"1":"44"}},{"t":"usc","label":"49 U.S.C. § 5324","url":"https://www.law.cornell.edu/uscode/text/49/5324","subs":["(b)(1)"],"by":{"1":"44"}},{"t":"usc","label":"54 U.S.C. § 302704","url":"https://www.law.cornell.edu/uscode/text/54/302704","stext":{"head":"§302704. Contracts and cooperative agreements","paras":[[0,"At the request of an Indian tribe whose preservation program has been approved to assume functions and responsibilities pursuant to section 302702 of this title, the Secretary shall enter into a contract or cooperative agreement with the Indian tribe permitting the assumption by the Indian tribe of any part of the responsibilities described in section 302304(b) of this title on tribal land, if—"],[1,"(1) the Secretary and the Indian tribe agree on additional financial assistance, if any, to the Indian tribe for the costs of carrying out those authorities;"],[1,"(2) the Secretary finds that the tribal historic preservation program has been demonstrated to be sufficient to carry out the contract or cooperative agreement and this division; and"],[1,"(3) the contract or cooperative agreement specifies the continuing responsibilities of the Secretary or of the appropriate State Historic Preservation Officers and provides for appropriate participation by—"],[2,"(A) the Indian tribe's traditional cultural authorities;"],[2,"(B) representatives of other Indian tribes whose traditional land is under the jurisdiction of the Indian tribe assuming responsibilities; and"],[2,"(C) the interested public."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/54/302704?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§302704. Contracts and cooperative agreements","tname":"National Park Service and Related Programs","by":{"1":"44"}},{"t":"law","label":"Pub. L. No. 113-4","url":"https://www.govinfo.gov/link/plaw/113/public/4","by":{"1":"45"}},{"t":"case","label":"Atlantic & Pac. R.R. v. Mingus","cite":"165 U.S. 413","y":1897,"id":"scdb/1896-105","sc":1,"op":1,"sum":"Congress did not intend by the statutes under which the Atlantic and Pacific Railroad Company received its grants of public land, to vest the lands absolutely in the company, without a right to the.Government to reacquire them on failure of the company to comply with the conditions of the grant; and no express provision for a forfeiture was necessary in order to fix the rights of 'the Government, and to …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"5, 7, 8","3":"6"}},{"t":"case","label":"Buster v. Wright","cite":"82 S.W. 855","y":1904,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./82/855/","by":{"2":"15"}},{"t":"case","label":"Choate v. Trapp","cite":"224 U.S. 665","y":1912,"id":"scdb/1911-240","sc":1,"op":1,"sum":"There is a broad distinction between the power to abrogate a statute and to destroy rights acquired under it; and while Congress, under its plenary power over Indian tribes, can amend or repeal an agreement by a later statute, it cannot destroy actually existing individual rights of property acquired under a former statute or agreement.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"11, 26"}},{"t":"case","label":"Choctaw Nation v. Oklahoma","cite":"397 U.S. 620","y":1970,"id":"1969/41","sc":1,"sum":"The Supreme Court held that the United States granted the Indian Nations rights to the riverbed of the Arkansas River where it was completely within the boundaries of the granted land and where it formed the border. Justice William O. Douglas concurred, writing that only the continuation of discrimination would justify denying the Indian Nations their claim.","sumSrc":"Oyez","by":{"2":"26"}},{"t":"case","label":"Colbert v. Fulton","cite":"157 P. 1151","y":1916,"court":"Okla.","url":"https://www.courtlistener.com/c/P./157/1151/","op":1,"by":{"2":"17"}},{"t":"case","label":"Duro v. Reina","cite":"495 U.S. 676","y":1990,"id":"1989/88-6546","sc":1,"op":1,"sum":"An Indian tribe may not assert criminal jurisdiction over a nonmember Indian.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2"}},{"t":"case","label":"George v. Robb","cite":"64 S.W. 615","y":1901,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./64/615/","op":1,"by":{"2":"17"}},{"t":"case","label":"Jones v. State","cite":"107 P. 738","y":1910,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./107/738/","op":1,"by":{"2":"34"}},{"t":"case","label":"McDougal v. McKay","cite":"237 U.S. 372","y":1915,"id":"scdb/1914-092","sc":1,"sum":"In construing an Act of Congress, its known purpose must be effectuated as nearly as may be.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"29"}},{"t":"case","label":"McGlassen v. State","cite":"130 P. 1174","y":1913,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./130/1174/","by":{"2":"33"}},{"t":"case","label":"Missouri, K. & T. Ry. Co. v. Phelps","cite":"76 S.W. 285","y":1903,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./76/285/","op":1,"by":{"2":"14"}},{"t":"case","label":"Moe v. Confederated Salish & Kootenai Tribes of the Flathead Reservation","cite":"425 U.S. 463","y":1976,"id":"1975/74-1656","sc":1,"sum":"An Indian tribe and some of its members residing on the tribal reservation in Montana brought actions challenging Montana's cigarette sales taxes and personal property taxes (in particular property taxes on motor vehicles) as applied to reservation Indians, and also the State's vendor licensing statute as applied to tribal members who sell cigarettes at \"smoke shops\" on the reservation, and seeking declaratory and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Muskogee Nat’l Tel. Co. v. Hall","cite":"64 S.W. 600","y":1901,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./64/600/","by":{"2":"15"}},{"t":"case","label":"Oklahoma Tax Comm’n v. Chickasaw Nation","cite":"515 U.S. 450","y":1995,"id":"1994/94-771","sc":1,"sum":"from enforcing several state taxes against the Tribe and its members. Pertinent here, the District Court held for the State on the motor fuels tax question, and largely for the Tribe on the income tax issue. The Court of Appeals ruled for the Tribe and its members on both issues, determining: (1) that, without congressional authorization, the State could not impose a motor fuels tax on fuel sold by the Tribe at its …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Palmer v. Cully","cite":"153 P. 154","y":1915,"court":"Okla.","url":"https://www.courtlistener.com/c/P./153/154/","op":2,"by":{"2":"25"}},{"t":"case","label":"Rollen v. State","cite":"125 P. 1087","y":1912,"court":"Okla. Crim. App.","url":"https://www.courtlistener.com/c/P./125/1087/","op":1,"by":{"2":"33"}},{"t":"case","label":"Stevens v. United States","cite":"146 F.2d 120","y":1944,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/146/120/","sum":"Finding it “clear that the marriage relations of Creek Indians in Oklahoma are subject to the laws of the state”.","sumSrc":"brief:2","by":{"2":"25"}},{"t":"case","label":"Stewart v. Keyes","cite":"295 U.S. 403","y":1935,"id":"scdb/1934-127","sc":1,"op":1,"by":{"2":"32"}},{"t":"case","label":"Tuttle v. Moore","cite":"64 S.W. 585","y":1901,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./64/585/","by":{"2":"9"}},{"t":"case","label":"Williams v. Lee","cite":"358 U.S. 217","y":1959,"id":"1958/39","sc":1,"sum":"The Court held that the jurisdiction of state courts does not extend to Indian reservations unless Congress specifically permits.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Zevely v. Weimer","cite":"82 S.W. 941","y":1904,"court":"Indian Terr.","url":"https://www.courtlistener.com/c/S.W./82/941/","by":{"2":"8, 15"}},{"t":"usc","label":"25 U.S.C. § 349","url":"https://www.law.cornell.edu/uscode/text/25/349","by":{"2":"8"}},{"t":"usc","label":"25 U.S.C. § 2719","url":"https://www.law.cornell.edu/uscode/text/25/2719","subs":["(a)(2)"],"stext":{"head":"§2719. Gaming on lands acquired after October 17, 1988","paras":[[0,"(a) Prohibition on lands acquired in trust by Secretary"],[0,"Except as provided in subsection (b), gaming regulated by this chapter shall not be conducted on lands acquired by the Secretary in trust for the benefit of an Indian tribe after October 17, 1988, unless—"],[1,"(1) such lands are located within or contiguous to the boundaries of the reservation of the Indian tribe on October 17, 1988; or"],[1,"(2) the Indian tribe has no reservation on October 17, 1988, and—"],[2,"(A) such lands are located in Oklahoma and—"],[3,"(i) are within the boundaries of the Indian tribe's former reservation, as defined by the Secretary, or"],[3,"(ii) are contiguous to other land held in trust or restricted status by the United States for the Indian tribe in Oklahoma; or"],[2,"(B) such lands are located in a State other than Oklahoma and are within the Indian tribe's last recognized reservation within the State or States within which such Indian tribe is presently located."],[0,"(b) Exceptions"],[0,"(1) Subsection (a) will not apply when—"],[1,"(A) the Secretary, after consultation with the Indian tribe and appropriate State and local officials, including officials of other nearby Indian tribes, determines that a gaming establishment on newly acquired lands would be in the best interest of the Indian tribe and its members, and would not be detrimental to the surrounding community, but only if the Governor of the State in which the gaming activity is to be conducted concurs in the Secretary's determination; or"],[1,"(B) lands are taken into trust as part of—"],[2,"(i) a settlement of a land claim,"],[2,"(ii) the initial reservation of an Indian tribe acknowledged by the Secretary under the Federal acknowledgment process, or"],[2,"(iii) the restoration of lands for an Indian tribe that is restored to Federal recognition."],[0,"(2) Subsection (a) shall not apply to—"],[1,"(A) any lands involved in the trust petition of the St. Croix Chippewa Indians of Wisconsin that is the subject of the action filed in the United States District Court for the District of Columbia entitled St. Croix Chippewa Indians of Wisconsin v. United States, Civ. No. 86–2278, or"],[1,"(B) the interests of the Miccosukee Tribe of Indians of Florida in approximately 25 contiguous acres of land, more or less, in Dade County, Florida, located within one mile of the intersection of State Road Numbered 27 (also known as Krome Avenue) and the Tamiami Trail."],[0,"(3) Upon request of the governing body of the Miccosukee Tribe of Indians of Florida, the Secretary shall, notwithstanding any other provision of law, accept the transfer by such Tribe to the Secretary of the interests of such Tribe in the lands described in paragraph (2)(B) and the Secretary shall declare that such interests are held in trust by the Secretary for the benefit of such Tribe and that such interests are part of the reservation of such Tribe under sections 5108 and 5110 of this title, subject to any encumbrances and rights that are held at the time of such transfer by any person or entity other than such Tribe. The Secretary shall publish in the Federal Register the legal description of any lands that are declared held in trust by the Secretary under this paragraph."],[0,"(c) Authority of Secretary not affected"],[0,"Nothing in this section shall affect or diminish the authority and responsibility of the Secretary to take land into trust."],[0,"(d) Application of title 26"],[0,"(1) The provisions of title 26 (including sections 1441, 3402(q), 6041, and 6050I, and chapter 35 of such title) concerning the reporting and withholding of taxes with respect to the winnings from gaming or wagering operations shall apply to Indian gaming operations conducted pursuant to this chapter, or under a Tribal-State compact entered into under section 2710(d)(3) of this title that is in effect, in the same manner as such provisions apply to State gaming and wagering operations."],[0,"(2) The provisions of this subsection shall apply notwithstanding any other provision of law enacted before, on, or after October 17, 1988, unless such other provision of law specifically cites this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/25/2719?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2719. Gaming on lands acquired after October 17, 1988","tname":"Indians","by":{"2":"23"}},{"t":"usc","label":"25 U.S.C. § 5101","url":"https://www.law.cornell.edu/uscode/text/25/5101","by":{"2":"22"}},{"t":"usc","label":"25 U.S.C. § 5203","url":"https://www.law.cornell.edu/uscode/text/25/5203","by":{"2":"31"}},{"t":"usc","label":"25 U.S.C. § 1911","url":"https://www.law.cornell.edu/uscode/text/25/1911","subs":["(a)"],"by":{"2":"40"}},{"t":"case","label":"Cherokee Nation v. Journeycake","cite":"155 U.S. 196","y":1894,"id":"scdb/1894-021","sc":1,"sum":"The Cherokees and the Delawares having, on the 8th day of April, 1867, in pursuance of the provisions of the treaty of July 19, 1866, 14 Stat. 799, between the United States and the Cherokee Nation, entered into a contract, whereby it was agreed that,, on the fulfilment by the Delawares of the stipulations on their part contained in said contract, all the members of that tribe, registered as provided in said …","sumSrc":"Headnote (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Delaware Indians v. Cherokee Nation","cite":"193 U.S. 127","y":1904,"id":"scdb/1903-208","sc":1,"sum":"In a suit brought under § 25 of the act of June 28, 1898, 30 Stat. 495, by the Delaware Indians residing in the Cherokee Nation for the purpose of determining their rights in and to the lands and funds of the Cherokee Nation under their contract and agreement with the Cherokee Nation of April 8, 1867.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"Dowell v. School Board of Oklahoma City Public Schools","cite":"219 F. Supp. 427","y":1963,"court":"W.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./219/427/","by":{"3":"23"}},{"t":"case","label":"Henry v. City of Muskogee","cite":"986 P.2d 1151","y":1999,"court":"Okla. Civ. App.","url":"https://www.courtlistener.com/c/P.2d/986/1151/","op":2,"ar":1,"by":{"3":"14"}},{"t":"case","label":"Minnesota v. Hitchcock","cite":"185 U.S. 373","y":1902,"id":"scdb/1901-038","sc":1,"op":1,"sum":"The original jurisdiction, vested by the Constitution in this court over controversies in which a State is a party, is not affected by the question whether the State is a party plaintifE or party defendant.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"4"}},{"t":"case","label":"Mosier v. Momsen","cite":"74 P. 905","y":1903,"court":"Okla.","url":"https://www.courtlistener.com/c/P./74/905/","by":{"3":"14"}},{"t":"case","label":"Scott v. Epperson","cite":"284 P. 19","y":1930,"court":"Okla.","url":"https://www.courtlistener.com/c/P./284/19/","by":{"3":"22-23"}},{"t":"case","label":"Spalding v. Chandler","cite":"160 U.S. 394","y":1896,"id":"scdb/1895-085","sc":1,"sum":"The Indian reservation at Sault Ste. Marie, under the treaty of June 26, 1820, with the CJiippewas, continued until extinguished by the treaty of August 2, 1855; and upon the extinguishment of the Indian title at that time the land.included in the reservation was made, by § 10 of the act of September 4,1841, not subject to preemption.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"9"}},{"t":"case","label":"State v. Romero","cite":"142 P.3d 887","y":2006,"court":"N.M.","url":"https://www.courtlistener.com/c/P.3d/142/887/","by":{"3":"10"}},{"t":"case","label":"United States v. Elliott","cite":"131 F.2d 720","y":1942,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/131/720/","by":{"3":"5"}},{"t":"case","label":"Winebrenner v. Forney","cite":"189 U.S. 148","y":1903,"id":"scdb/1902-110","sc":1,"sum":"Where there is a seeming contradiction between two clauses in a proclamation opening lands for settlement, the first clause being a special description of a strip of land, and the second being-found in a portion of the proclamation defining the purposes for which the strip is made, the first clause is entitled to preference.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"6"}},{"t":"case","label":"OTHER AUTHORITIES Brief for Petitioners, Nebraska v. Parker","cite":"136 S. Ct. 1072","y":2016,"url":"https://www.courtlistener.com/c/S.%20Ct./136/1072/","sc":1,"by":{"3":"17"}},{"t":"case","label":"Brief for United States as Amicus Curiae Supporting Petitioner, Oklahoma v. Brooks","cite":"490 U.S. 1031","y":1989,"url":"https://supreme.justia.com/cases/federal/us/490/1031/","sc":1,"by":{"3":"26, 3"}}]};